import { loadRunnerCredential } from "./credentialFile.js";
import { parseModelKey } from "../shared/modelKeys.js";

/***
 * MARK: loadRunnerConfig
 * @description Reads Runner daemon configuration from the environment.
 *   The credential is collected by itself after human approval (one-click
 *   onboarding, D4): when it is absent the daemon registers, polls until
 *   the join is approved, stores the handed-over credential, and keeps
 *   booting. Only when the handover cannot complete (e.g. a restart lost
 *   the join nonce) does it exit asking for the pasted credential.
 *   Assignment is explicit (project + task ids) by default; set
 *   KAINBAIN_RUNNER_DISPATCH=1 for the capability-aware dispatch loop
 *   (WP-3.1), optionally scoped with KAINBAIN_RUNNER_PROJECTS.
 * @example loadRunnerConfig({ KAINBAIN_RUNNER_ID: 'r1' }) => { runnerId: 'r1', ... }
 * @param {Object} [env] - Environment mapping (defaults to process.env).
 * @returns {Object} Normalized config.
 ***/
export function loadRunnerConfig(env = process.env) {
	const errors = [];
	const str = (key, fallback = "") => {
		const value = env[key] ?? fallback;
		return typeof value === "string" ? value.trim() : String(value ?? "").trim();
	};

	const backendUrl = str("KAINBAIN_RUNNER_BACKEND", "http://localhost:3100").replace(/\/+$/, "");
	const runnerId = str("KAINBAIN_RUNNER_ID", "");
	// Multi-harness service (one Runner, several harnesses): the csv
	// KAINBAIN_RUNNER_HARNESSES wins when set; otherwise the singular
	// KAINBAIN_RUNNER_HARNESS seeds a 1-element list. The first entry
	// stays the primary harness (single-assignment default, posture).
	// Auto-detect is the default: an empty harness config or a literal
	// "auto" token means the daemon probes the host on boot (PATH, the
	// standard install dirs, per-harness install dirs, KAINBAIN_*_BIN
	// overrides, and the pi agent snapshot — see detectAvailableHarnesses
	// in daemon.js) and fail-fasts when nothing is found. Pass --manual
	// --harness NAME at install time to pin.
	const isAutoToken = (h) => String(h ?? "").trim().toLowerCase() === "auto";
	let harnessAuto = false;
	const harnessIds = str("KAINBAIN_RUNNER_HARNESSES", "")
		.split(",")
		.map((h) => h.trim())
		.filter(Boolean)
		.filter((h) => {
			if (isAutoToken(h)) {
				harnessAuto = true;
				return false;
			}
			return true;
		});
	const singularHarness = str("KAINBAIN_RUNNER_HARNESS", "");
	if (isAutoToken(singularHarness)) {
		harnessAuto = true;
	} else if (harnessIds.length === 0 && singularHarness) {
		harnessIds.push(singularHarness);
	}
	if (harnessIds.length === 0 && !singularHarness) {
		// Default behaviour: auto-detect (no --manual flag given).
		harnessAuto = true;
	}
	const harnessId = harnessIds[0] ?? "";
	// Servable model advertisement (capability matching is backend-side, so
	// the list is the operator's claim of what this host can run; the
	// dispatch answer carries the required model per assignment and the
	// daemon serves exactly that). KAINBAIN_RUNNER_MODELS (csv) sets the
	// pin; otherwise the singular KAINBAIN_RUNNER_MODEL seeds a 1-element
	// pin. Periodic model auto-discovery (every
	// KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS, default 12h) runs even
	// when pinned: the advertised list is pin ∪ discovered (survey q2 — a
	// newly released harness model appears automatically), so the pin is
	// never lost to a broken scan. Opt in to discovery-wins with
	// KAINBAIN_RUNNER_MODEL_DISCOVERY_WINS=1: a non-empty discovery result
	// then replaces the pin. Empty everywhere means unpinned (matches
	// model-less tasks only).
	// The "default" sentinel means harness-managed (no pinned model),
	// never a model this host can serve, so it is never advertised:
	// an operator who sets KAINBAIN_RUNNER_MODEL=default gets the
	// unpinned behaviour, not a fake capability the backend could
	// match against. Duplicates carry no information either.
	const isServableModelName = (name) =>
		Boolean(name) && name.toLowerCase() !== "default";
	// Canonical pin validation (survey q7/q8: malformed ids are blocked
	// from being saved/advertised, never fatal). A pin must parse as a
	// harness-scoped fleet key (`harness::provider::model[::effort]`);
	// when the runner pins explicit harnesses WITHOUT auto-detect the
	// pin's harness must be one of them (auto-detect installs skip the
	// membership check — the final set is still unknown at load, and a
	// mixed `muse,auto` pin plus a pi model is valid when the host has
	// pi; pins for never-detected harnesses are marked stale downstream,
	// never fatal). Drops collect into `warnings` (surfaced via
	// `facts.errors` + one boot log line per drop) so a typo (e.g.
	// `deepseek-v4-flash:0731-cloud`, a 2-part provider key for a harness
	// that is not enabled) can never be advertised.
	const warnings = [];
	const harnessSet = new Set(harnessIds);
	const checkPinMembership = !harnessAuto && harnessSet.size > 0;
	const pinRejection = (id) => {
		const parsed = parseModelKey(id);
		if (!parsed || (parsed.form !== "harness" && parsed.form !== "harnessReasoning")) {
			return `ignoring KAINBAIN_RUNNER_MODELS entry '${id}': not a harness::provider::model[::effort] id`;
		}
		if (checkPinMembership && !harnessSet.has(parsed.harness)) {
			return `ignoring KAINBAIN_RUNNER_MODELS entry '${id}': harness '${parsed.harness}' is not in KAINBAIN_RUNNER_HARNESSES [${harnessIds.join(", ")}]`;
		}
		return null;
	};
	const model = str("KAINBAIN_RUNNER_MODEL", "");
	const rawSingularModel = isServableModelName(model) ? model : "";
	const singularRejection = rawSingularModel ? pinRejection(rawSingularModel) : null;
	if (singularRejection) {
		warnings.push(singularRejection.replace("KAINBAIN_RUNNER_MODELS entry", "KAINBAIN_RUNNER_MODEL"));
	}
	const cleanedSingularModel = singularRejection ? "" : rawSingularModel;
	const models = [];
	const seenPins = new Set();
	for (const candidate of str("KAINBAIN_RUNNER_MODELS", "").split(",")) {
		const trimmed = candidate.trim();
		if (!isServableModelName(trimmed) || seenPins.has(trimmed)) continue;
		seenPins.add(trimmed);
		const rejection = pinRejection(trimmed);
		if (rejection) {
			warnings.push(rejection);
			continue;
		}
		models.push(trimmed);
	}
	if (models.length === 0 && cleanedSingularModel) models.push(cleanedSingularModel);
	const projectId = str("KAINBAIN_RUNNER_PROJECT_ID", "");
	const taskId = str("KAINBAIN_RUNNER_TASK_ID", "");
	if (!runnerId) errors.push("KAINBAIN_RUNNER_ID is required (stable per host).");
	if (!harnessId && !harnessAuto)
		errors.push("KAINBAIN_RUNNER_HARNESS is required (e.g. pi, codex, mock).");
	const dispatch = str("KAINBAIN_RUNNER_DISPATCH", "") === "1";
	if (!dispatch && !projectId) {
		errors.push("KAINBAIN_RUNNER_PROJECT_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
	}
	if (!dispatch && !taskId) {
		errors.push("KAINBAIN_RUNNER_TASK_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
	}

	// Self-update channel (Option A, ADR 0012): pull-based, idle-only, and
	// signature-verified against the pinned key in runner/updates/verify.js.
	// KAINBAIN_RUNNER_UPDATE_URL overrides the release pointer for
	// air-gapped mirrors (full manifest.json URL or a base serving
	// manifest.json + manifest.json.minisig + assets).
	const updateUrl = str(
		"KAINBAIN_RUNNER_UPDATE_URL",
		"https://api.github.com/repos/Ewrdad/Kainbain/releases/latest",
	);
	const autoUpdate = str("KAINBAIN_RUNNER_AUTO_UPDATE", "1") !== "0";
	const updateCheckIntervalMs = Number.parseInt(
		str("KAINBAIN_RUNNER_UPDATE_CHECK_INTERVAL_MS", "3600000"),
		10,
	);

	// Model auto-discovery cadence (one leg per configured harness),
	// default 12h. 0 disables all scanning (boot seed and re-detect
	// alike). Discovered ids are UNIONED onto the operator's explicit
	// MODELS/MODEL pin by default (pin never drops); KAINBAIN_RUNNER_
	// MODEL_DISCOVERY_WINS=1 opts in to discovery-replaces-pin instead.
	// Invalid values fall back to 12h.
	const modelDiscoveryIntervalMs = Number.parseInt(
		str("KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS", "43200000"),
		10,
	);
	const heartbeatMs = Number.parseInt(str("KAINBAIN_RUNNER_HEARTBEAT_MS", "15000"), 10);
	const approvalPollMs = Number.parseInt(str("KAINBAIN_RUNNER_APPROVAL_POLL_MS", "5000"), 10);
	const approvalTimeoutMs = Number.parseInt(str("KAINBAIN_RUNNER_APPROVAL_TIMEOUT_MS", "300000"), 10);
	const dispatchPollMs = Number.parseInt(str("KAINBAIN_RUNNER_DISPATCH_POLL_MS", "5000"), 10);
	const dispatchIdleLimit = Number.parseInt(str("KAINBAIN_RUNNER_DISPATCH_IDLE_LIMIT", "3"), 10);
	// Impromptu T0 channel (ADR 0014): idle runners also poll for read-only
	// jobs (retrospective chat turns) when a dispatch iteration yields no
	// task work. `=0` opts out (task work only).
	const impromptu = str("KAINBAIN_RUNNER_IMPROMPTU", "1") !== "0";

	return {
		backendUrl,
		home: str("HOME", ""),
		installRoot: str("KAINBAIN_RUNNER_INSTALL_ROOT", ""),
		updateUrl,
		autoUpdate,
		updateCheckIntervalMs:
			Number.isFinite(updateCheckIntervalMs) && updateCheckIntervalMs >= 300000
				? updateCheckIntervalMs
				: 3600000,
		joinToken: str("KAINBAIN_RUNNER_JOIN_TOKEN", ""),
		// Credential precedence: explicit env wins; otherwise the
		// previously collected credential file (one-click approval writes
		// it); otherwise empty, which routes the daemon into the join
		// flow. HOME comes from the env mapping only (startRunner.sh
		// always sets it), so tests with fake envs never touch disk.
		credential:
			str("KAINBAIN_RUNNER_CREDENTIAL", "") ||
			(str("HOME", "") ? loadRunnerCredential(runnerId, str("HOME", "")) : ""),
		runnerId,
		harnessId,
		harnessIds,
		harnessAuto,
		model: cleanedSingularModel,
		models,
		tiers: str("KAINBAIN_RUNNER_TIERS", "T0,T1")
			.split(",")
			.map((t) => t.trim())
			.filter(Boolean),
		workRoot: str("KAINBAIN_RUNNER_WORK_ROOT", "runner-work"),
		projectId,
		taskId,
		dispatch,
		impromptu,
		projectIds: str("KAINBAIN_RUNNER_PROJECTS", "")
			.split(",")
			.map((p) => p.trim())
			.filter(Boolean),
		dispatchPollMs: Number.isFinite(dispatchPollMs) && dispatchPollMs > 0 ? dispatchPollMs : 5000,
		dispatchIdleLimit:
			Number.isFinite(dispatchIdleLimit) && dispatchIdleLimit >= 0 ? dispatchIdleLimit : 3,
		heartbeatMs: Number.isFinite(heartbeatMs) && heartbeatMs > 0 ? heartbeatMs : 15000,
