import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { loadRunnerConfig } from "./config.js";
import {
	credentialFilePathFor,
	loadRunnerCredential,
	saveRunnerCredential,
	shortRunnerId,
} from "./credentialFile.js";

describe("loadRunnerConfig", () => {
	it("fills defaults and reports no errors when complete", () => {
		const config = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: " r1 ",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_PROJECT_ID: "p1",
			KAINBAIN_RUNNER_TASK_ID: "t1",
		});
		assert.equal(config.errors.length, 0);
		assert.equal(config.runnerId, "r1");
		assert.equal(config.backendUrl, "http://localhost:3100");
		assert.deepEqual(config.tiers, ["T0", "T1"]);
		assert.equal(config.heartbeatMs, 15000);
	});

	it("lists every missing required key (harness defaults to auto-detect)", () => {
		const config = loadRunnerConfig({});
		assert.equal(config.errors.length, 3);
		assert.match(config.errors.join(" "), /KAINBAIN_RUNNER_ID/);
		assert.equal(config.harnessAuto, true);
	});

	it("drops the explicit-assignment requirement in dispatch mode", () => {
		const config = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_PROJECTS: " p1 , p2 ",
			KAINBAIN_RUNNER_DISPATCH_IDLE_LIMIT: "nope",
		});
		assert.equal(config.errors.length, 0);
		assert.equal(config.dispatch, true);
		assert.deepEqual(config.projectIds, ["p1", "p2"]);
		assert.equal(config.dispatchPollMs, 5000);
		assert.equal(config.dispatchIdleLimit, 3);
	});

	it("keeps dispatchIdleLimit 0 as persistent service mode", () => {
		const config = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_DISPATCH_IDLE_LIMIT: "0",
		});
		assert.equal(config.errors.length, 0);
		assert.equal(config.dispatchIdleLimit, 0);
	});

	it("advertises a csv MODELS list, singular MODEL seeds it, empty stays unpinned", () => {
		const csv = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESSES: "pi,muse",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_MODEL: "ignored-when-csv",
			KAINBAIN_RUNNER_MODELS: " pi::a::1 ,muse::b::2,, pi::a::1 ",
		});
		assert.deepEqual(csv.models, ["pi::a::1", "muse::b::2"]);
		assert.equal(csv.model, "");

		const single = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "pi",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_MODEL: "pi::prov::m1",
		});
		assert.deepEqual(single.models, ["pi::prov::m1"]);

		const bare = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "pi",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.deepEqual(bare.models, []);
		assert.equal(bare.model, "");
	});

	it("never advertises the default sentinel or duplicate models", () => {
		const sentinel = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "pi",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_MODEL: "default",
		});
		assert.deepEqual(sentinel.models, []);
		assert.equal(sentinel.model, "");

		const mixed = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "pi",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_MODELS: "default, pi::p::m1, pi::p::m1, Default, pi::p::m2",
		});
		assert.deepEqual(mixed.models, ["pi::p::m1", "pi::p::m2"]);
	});

	it("drops malformed model pins with a warning instead of advertising them", () => {
		const base = {
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESSES: "muse",
			KAINBAIN_RUNNER_DISPATCH: "1",
		};
		// N2 evidence: a 2-part provider key was advertised as-is.
		const legacy = loadRunnerConfig({ ...base, KAINBAIN_RUNNER_MODELS: "deepseek-v4-flash:0731-cloud" });
		assert.deepEqual(legacy.models, []);
		assert.equal(legacy.warnings.length, 1);
		assert.match(legacy.warnings[0], /deepseek-v4-flash:0731-cloud/);
		assert.match(legacy.warnings[0], /harness::provider::model/);

		// A well-formed key for a harness that is not enabled is dropped too.
		const foreign = loadRunnerConfig({ ...base, KAINBAIN_RUNNER_MODELS: "ollama-cloud-direct::gemma4:31b-cloud" });
		assert.deepEqual(foreign.models, []);
		assert.equal(foreign.warnings.length, 1);
		assert.match(foreign.warnings[0], /ollama-cloud-direct::gemma4:31b-cloud/);

		// Wrong-harness pins are dropped (once per id); good ones survive in order.
		const mixed = loadRunnerConfig({
			...base,
			KAINBAIN_RUNNER_MODELS: "pi::x::y, muse::meta::a, pi::x::y, bare, muse::meta::b::high",
		});
		assert.deepEqual(mixed.models, ["muse::meta::a", "muse::meta::b::high"]);
		assert.equal(mixed.warnings.length, 2);
		assert.ok(mixed.warnings.some((w) => w.includes("pi::x::y") && w.includes("KAINBAIN_RUNNER_HARNESSES")));
		assert.ok(mixed.warnings.some((w) => w.includes("bare")));

		// An invalid singular MODEL is dropped as well (never advertised).
		const singular = loadRunnerConfig({ ...base, KAINBAIN_RUNNER_MODEL: "m1" });
		assert.deepEqual(singular.models, []);
		assert.equal(singular.model, "");
		assert.equal(singular.warnings.length, 1);
		assert.match(singular.warnings[0], /KAINBAIN_RUNNER_MODEL/);

		// A valid singular MODEL still seeds the pin.
		const valid = loadRunnerConfig({ ...base, KAINBAIN_RUNNER_MODEL: "muse::meta::a" });
		assert.deepEqual(valid.models, ["muse::meta::a"]);
		assert.equal(valid.model, "muse::meta::a");
		assert.deepEqual(valid.warnings, []);

		// Auto-detect installs skip the membership check (nothing is
		// enabled yet) but still enforce the fleet grammar.
		const auto = loadRunnerConfig({ KAINBAIN_RUNNER_ID: "r1", KAINBAIN_RUNNER_DISPATCH: "1", KAINBAIN_RUNNER_MODELS: "pi::x::y, garbage" });
		assert.deepEqual(auto.models, ["pi::x::y"]);
		assert.equal(auto.warnings.length, 1);

		// Mixed explicit-plus-auto installs also skip membership: the
		// final harness set is still unknown at load, so a pin for a
		// not-yet-detected harness is kept (pins for never-detected
		// harnesses are marked stale downstream, never fatal here).
		const mixedAuto = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESSES: "muse,auto",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_MODELS: "pi::x::y, garbage",
		});
		assert.equal(mixedAuto.harnessAuto, true);
		assert.deepEqual(mixedAuto.models, ["pi::x::y"]);
		assert.equal(mixedAuto.warnings.length, 1);

		// Dropping everything behaves as unpinned (matches model-less tasks).
		const emptied = loadRunnerConfig({ ...base, KAINBAIN_RUNNER_MODELS: "nope" });
		assert.deepEqual(emptied.models, []);
		assert.equal(emptied.model, "");
	});

	it("defaults the discovery staleness threshold to 24h, honours overrides, clamps garbage", () => {
		const env = {
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
		};
		assert.equal(loadRunnerConfig(env).modelDiscoveryStaleMs, 86400000);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_DISCOVERY_STALE_MS: "3600000" }).modelDiscoveryStaleMs,
			3600000,
		);
		assert.equal(loadRunnerConfig({ ...env, KAINBAIN_RUNNER_DISCOVERY_STALE_MS: "soon" }).modelDiscoveryStaleMs, 86400000);
		assert.equal(loadRunnerConfig({ ...env, KAINBAIN_RUNNER_DISCOVERY_STALE_MS: "0" }).modelDiscoveryStaleMs, 86400000);
		assert.equal(loadRunnerConfig({ ...env, KAINBAIN_RUNNER_DISCOVERY_STALE_MS: "-5" }).modelDiscoveryStaleMs, 86400000);
	});

	it("reads a csv HARNESSES list, singular HARNESS seeds it", () => {
		const multi = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESSES: " pi ,muse,, vibe ",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.equal(multi.errors.length, 0);
		assert.deepEqual(multi.harnessIds, ["pi", "muse", "vibe"]);
		assert.equal(multi.harnessId, "pi");

		const single = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_PROJECT_ID: "p1",
			KAINBAIN_RUNNER_TASK_ID: "t1",
		});
		assert.equal(single.errors.length, 0);
		assert.deepEqual(single.harnessIds, ["mock"]);
		assert.equal(single.harnessId, "mock");
	});

	it("defaults the update channel to the GitHub releases pointer with auto-update on", () => {
		const config = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.equal(config.errors.length, 0);
		assert.equal(config.updateUrl, "https://api.github.com/repos/Ewrdad/Kainbain/releases/latest");
		assert.equal(config.autoUpdate, true);
		assert.equal(config.updateCheckIntervalMs, 3600000);
	});

	it("honours the air-gapped mirror override and update opt-out", () => {
		const config = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
			KAINBAIN_RUNNER_UPDATE_URL: "https://mirror.local/r/manifest.json",
			KAINBAIN_RUNNER_AUTO_UPDATE: "0",
			KAINBAIN_RUNNER_UPDATE_CHECK_INTERVAL_MS: "100",
		});
		assert.equal(config.updateUrl, "https://mirror.local/r/manifest.json");
		assert.equal(config.autoUpdate, false);
		assert.equal(config.updateCheckIntervalMs, 3600000);
	});

	it("auto-detects by default and honours explicit manual pins", () => {
		const empty = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.equal(empty.errors.length, 0);
		assert.equal(empty.harnessAuto, true);
		assert.deepEqual(empty.harnessIds, []);

		const literal = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "auto",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.equal(literal.errors.length, 0);
		assert.equal(literal.harnessAuto, true);

		const mixed = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESSES: "auto,mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.equal(mixed.errors.length, 0);
		assert.equal(mixed.harnessAuto, true);
		assert.deepEqual(mixed.harnessIds, ["mock"]);

		const manual = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "pi",
			KAINBAIN_RUNNER_DISPATCH: "1",
		});
		assert.equal(manual.errors.length, 0);
		assert.equal(manual.harnessAuto, false);
		assert.deepEqual(manual.harnessIds, ["pi"]);
	});

	it("falls back on invalid numbers and customizes tiers", () => {
		const config = loadRunnerConfig({
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_PROJECT_ID: "p1",
			KAINBAIN_RUNNER_TASK_ID: "t1",
			KAINBAIN_RUNNER_HEARTBEAT_MS: "nan",
			KAINBAIN_RUNNER_TIERS: "T0",
		});
		assert.equal(config.heartbeatMs, 15000);
		assert.deepEqual(config.tiers, ["T0"]);
	});

	it("polls impromptu jobs by default, =0 opts out", () => {
		const env = {
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
		};
		assert.equal(loadRunnerConfig(env).impromptu, true);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_IMPROMPTU: "0" }).impromptu,
			false,
		);
	});

	it("defaults model discovery to 12h, honours 0/off, clamps garbage", () => {
		const env = {
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
		};
		assert.equal(loadRunnerConfig(env).modelDiscoveryIntervalMs, 43200000);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS: "0" }).modelDiscoveryIntervalMs,
			0,
		);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS: "3600000" }).modelDiscoveryIntervalMs,
			3600000,
		);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS: "soon" }).modelDiscoveryIntervalMs,
			43200000,
		);
	});

	it("keeps pin-wins by default, =1 opts in to discovery-wins", () => {
		const env = {
			KAINBAIN_RUNNER_ID: "r1",
			KAINBAIN_RUNNER_HARNESS: "mock",
			KAINBAIN_RUNNER_DISPATCH: "1",
		};
		assert.equal(loadRunnerConfig(env).modelDiscoveryWins, false);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_WINS: "1" }).modelDiscoveryWins,
			true,
		);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_WINS: "0" }).modelDiscoveryWins,
			false,
		);
	});
});

describe("runner credential file (one-click approval)", () => {
	it("names the file like startRunner.sh names the env file (local- stripped)", () => {
