		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS: "3600000" }).modelDiscoveryIntervalMs,
			3600000,
		);
		assert.equal(
			loadRunnerConfig({ ...env, KAINBAIN_RUNNER_MODEL_DISCOVERY_INTERVAL_MS: "soon" }).modelDiscoveryIntervalMs,
