describe("joinAndHeartbeat command channel", () => {
	const quiet = { log: () => {}, warn: () => {} };

	it("first-heartbeat facts name every configured harness and surface pin warnings", async () => {
		clearDiscoveredModelsCache();
		const heartbeats = [];
		const warnings = [];
		const config = baseConfig({
			harnessIds: ["mock"],
			warnings: ["ignoring KAINBAIN_RUNNER_MODELS entry 'nope': not a fleet id"],
			autoUpdate: false,
		});
		const client = {
			setCredential: () => {},
			heartbeat: async (args) => {
				heartbeats.push(args);
				return { status: "active" };
			},
		};
		const { stop } = await joinAndHeartbeat({
			config,
			client,
			loadHarness: async () => fakeHarness(),
			logger: { log: () => {}, warn: (m) => warnings.push(m) },
			state: {},
		});
		try {
			assert.ok(heartbeats.length >= 1);
			const facts = heartbeats[0].facts;
			// mock has no discovery leg and the seed round cannot scan
			// it — the heartbeat must still name it, never read {}.
			assert.deepEqual(Object.keys(facts.discoveryStatus), ["mock"]);
			assert.equal(facts.discoveryStatus.mock.error.code, "NOT_YET_RUN");
			// Dropped pins surface in facts.errors AND the boot log.
			assert.ok(facts.errors.includes("ignoring KAINBAIN_RUNNER_MODELS entry 'nope': not a fleet id"));
			assert.ok(warnings.some((w) => w.includes("Runner config:") && w.includes("nope")));
		} finally {
			stop();
			fs.rmSync(config.workRoot, { recursive: true, force: true });
			clearDiscoveredModelsCache();
		}
	});

	it("acts on commands queued while the runner was down (boot delivery)", async () => {
		// autoUpdate:false keeps this hermetic (no real check runs); the
		// ack is a FAILED skip naming the opt-out switch, never a quiet
		// success — the operator must see that nothing was applied.
		const config = baseConfig({ harnessIds: ["mock"], autoUpdate: false });
		const client = {
			setCredential: () => {},
			heartbeat: async () => ({ status: "active", pendingCommands: ["requestUpdate"] }),
		};
		const state = {};
		const { stop } = await joinAndHeartbeat({
			config,
			client,
			loadHarness: async () => fakeHarness(),
			logger: quiet,
			state,
		});
		try {
			assert.equal(state.commandAcks.length, 1);
			assert.equal(state.commandAcks[0].command, "requestUpdate");
			assert.equal(state.commandAcks[0].ok, false);
			assert.match(state.commandAcks[0].detail, /KAINBAIN_RUNNER_AUTO_UPDATE=0/);
		} finally {
			stop();
			fs.rmSync(config.workRoot, { recursive: true, force: true });
		}
	});
});

describe("collectTaskFiles docsDirName", () => {
	it("reads files from a custom docs folder", async () => {
		const fs = (await import("node:fs")).default;
		const os = (await import("node:os")).default;
		const path = (await import("node:path")).default;
		const { collectTaskFiles } = await import("./daemon.js");
		const workdir = fs.mkdtempSync(path.join(os.tmpdir(), "kb-wt-"));
		try {
			fs.mkdirSync(path.join(workdir, "kdocs", "tasks", "t1"), { recursive: true });
			fs.writeFileSync(path.join(workdir, "kdocs", "tasks", "t1", "SURVEY.md"), "x");
			const files = collectTaskFiles({ workdir, taskId: "t1", docsDirName: "kdocs" });
			assert.deepEqual(files, [{ name: "SURVEY.md", content: "x" }]);
			const invalid = collectTaskFiles({ workdir, taskId: "t1", docsDirName: "../escape" });
			assert.deepEqual(invalid, []);
		} finally {
			fs.rmSync(workdir, { recursive: true, force: true });
		}
	});
});

